130	  if (!Number.isInteger(pid) || pid <= 0) return false;
131	  try {
132	    process.kill(pid, 0);
133	    return true;
134	  } catch (error) {
135	    return (error as NodeJS.ErrnoException).code === 'EPERM';
136	  }
137	}
138	
139	function processGroupAlive(pgid: number): boolean {
140	  if (!Number.isInteger(pgid) || pgid <= 1 || process.platform === 'win32') return false;
141	  try {
142	    process.kill(-pgid, 0);
143	    return true;
144	  } catch (error) {
145	    return (error as NodeJS.ErrnoException).code === 'EPERM';
146	  }
147	}
148	
149	function slotReclaimable(occupant: SlotOccupant, file: string, now: number, staleMs: number): boolean {
150	  if (occupant.state === 'missing') return true;
151	  if (occupant.state === 'valid') {
152	    const isolated = occupant.meta.providerProcessGroupIsolated === true;
153	    const providerPgid = ownNumber(occupant.meta, 'providerPgid');
154	    // Once the admission has transferred to an isolated provider group, the
155	    // group—not the supervising worker—is the capacity owner. A crashed worker
156	    // may leave children alive, so reclaim only after the exact PGID disappears.
157	    if (isolated && providerPgid !== null && processGroupAlive(providerPgid)) return false;
158	    return !pidAlive(occupant.pid);
159	  }
160	  try {
161	    const ageMs = now - statSync(file).mtimeMs;
162	    return !Number.isFinite(ageMs) || ageMs > staleMs;
163	  } catch {
164	    // Fail closed: an existing slot we cannot stat still occupies capacity.
165	    return false;
166	  }
167	}
