189	export function writeProviderProcessSlotExclusive(
190	  file: string,
191	  meta: ProviderProcessSlotFileMeta,
192	): boolean {
193	  try {
194	    writeFileSync(file, JSON.stringify(meta), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
