239	function currentProcessStartTimeMs(): number {
240	  return Math.floor(Date.now() - process.uptime() * 1_000);
241	}
242	
243	function sameProcessStart(left: number | undefined, right: number | undefined): boolean {
244	  if (left === undefined || right === undefined) return true;
245	  return Math.abs(left - right) <= 2_000;
246	}
