248	// B-137a:F-124 — used at the classifyExistingLock wiring below, so NOT dead
249	// code; the `export` was the only dead part (no importer anywhere in
250	// packages/main/src or scripts). Narrowed to module-private.
251	function classifyProviderRegistryLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
252	  const holder = snapshot.holder;
253	  if (!holder || holder.hostname !== hostname()) return 'unknown';
254	  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
255	  try {
256	    process.kill(holder.pid, 0);
257	  } catch (error) {
258	    const code = (error as NodeJS.ErrnoException).code;
259	    if (code === 'ESRCH') return 'stale';
260	    if (code !== 'EPERM') return 'unknown';
261	  }
262	  if (
263	    holder.pid === process.pid
264	    && !sameProcessStart(holder.processStartTimeMs, currentProcessStartTimeMs())
265	  ) return 'stale';
266	  return 'active';
267	}
