269	function withProviderRegistryLock<T>(
270	  dir: string,
271	  fn: () => T,
272	  timing: ProviderRegistryLockTiming = {},
273	): T {
274	  const lock = acquireMkdirLock(`${dir}.lock`, {
275	    label: 'provider-process-registry',
276	    deadlineMs: timing.deadlineMs ?? 30_000,
277	    staleMs: timing.staleMs ?? 10_000,
278	    pollMs: timing.pollMs ?? 10,
279	    requireHolderToken: true,
280	    classifyExistingLock: classifyProviderRegistryLock,
281	    holderInfo: {
282	      pid: process.pid,
283	      hostname: hostname(),
284	      command: 'provider-process-registry mutation',
285	      acquiredAt: new Date().toISOString(),
286	      lockId: randomUUID(),
287	      processStartTimeMs: currentProcessStartTimeMs(),
288	    },
289	  });
290	  try {
291	    return fn();
292	  } finally {
293	    lock.release();
294	  }
295	}
