297	export function scanLiveProviderProcessSlots(
298	  dir: string,
299	  now: number,
300	  staleMs: number,
301	  lockTiming: ProviderRegistryLockTiming = {},
302	): ProviderProcessLiveDescriptor[] {
303	  return withProviderRegistryLock(dir, () => scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs), lockTiming);
