306	export function acquireProviderProcessSlot(
307	  dir: string,
308	  cap: number,
309	  staleMs: number,
310	  now: number,
311	  meta: ProviderProcessSlotMeta,
312	  lockTiming: ProviderRegistryLockTiming = {},
313	): AcquiredProviderProcessSlot | null {
314	  mkdirSync(dir, { recursive: true });
315	  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
316	    ? cap
317	    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
318	  return withProviderRegistryLock(dir, () => {
319	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
320	    if (live.length >= boundedCap) return null;
321	    const token = randomUUID();
322	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
323	    for (let index = 0; index < boundedCap; index += 1) {
324	      const file = join(dir, `slot-${index}.json`);
325	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
326	      const judged = readSlotOccupant(file);
327	      if (!slotReclaimable(judged, file, now, staleMs)) continue;
328	      if (judged.state !== 'missing') {
329	        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
330	        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
331	      }
332	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
333	    }
334	    return null;
335	  }, lockTiming);
336	}
