338	export function releaseProviderProcessSlot(
339	  file: string | null,
340	  token: string | null,
341	  lockTiming: ProviderRegistryLockTiming = {},
342	  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
343	): void {
344	  if (!file || !token) return;
345	  const dir = dirname(file);
346	  withProviderRegistryLock(dir, () => {
347	    const occupant = readSlotOccupant(file);
348	    if (occupant.state !== 'valid' || occupant.token !== token) return;
349	    mutationOps.unlink(file);
350	  }, lockTiming);
351	}
