 47	export function acquireProviderProcessAdmission(
 48	  request: ProviderProcessAdmissionRequest,
 49	): ProviderProcessAdmission {
 50	  const dir = providerProcessSlotsDir(request.root);
 51	  const cap = resolveProviderProcessMaxConcurrent(request.env);
 52	  const staleMs = resolveProviderProcessSlotStaleMs(request.env);
 53	  const slot = acquireProviderProcessSlot(dir, cap, staleMs, Date.now(), {
 54	    pid: request.pid ?? process.pid,
 55	    startedAt: request.startedAt ?? new Date().toISOString(),
 56	    host: request.host,
 57	    storyId: request.storyId,
 58	    agentType: request.agentType,
 59	  });
 60	  return {
 61	    admitted: slot !== null,
 62	    slot,
 63	    cap,
 64	    // B-137a:F-126 — DIAGNOSTIC-ONLY, and deliberately a post-refusal snapshot.
 65	    //
 66	    // The admission DECISION is already made above, atomically under the
 67	    // registry lock. This scan runs after that lock is released, with a fresh
 68	    // Date.now(), so it can legitimately disagree with the decision: a slot
 69	    // freed in between makes the list shorter than `cap` even though the
 70	    // refusal was correct at decision time. That is why it never feeds a gate.
 71	    //
 72	    // Holding the lock across the scan would make the two agree but would
 73	    // serialize every refusal behind a directory walk, adding contention to the
 74	    // exact path that is already saturated. The snapshot is described as
 75	    // approximate at its user-facing consumer (host-run.ts refusalDetail)
 76	    // instead of being presented as an authoritative count.
 77	    liveRuns: slot ? [] : scanLiveProviderProcessSlots(dir, Date.now(), staleMs),
 78	  };
 79	}
