  219	/**
  220	 * F-004: build the redacted env the review-only codex subprocess is allowed to see,
  221	 * from the base process env and the authorized policy. CLOSED-ALLOWLIST BY
  222	 * CONSTRUCTION (root fix — closes the credential-leak class the earlier
  223	 * denylist/allowlist-injection semantics kept re-opening):
  224	 *   1. A name is forwarded ONLY if `isSafeBaseEnvName(name)` is true — i.e. it is in
  225	 *      the hardcoded minimal SAFE_BASE_ENV set a CLI needs (PATH/HOME/locale/tmp/tty/
  226	 *      identity, plus exact standard LC_* locale categories). Every other name is DROPPED. An unknown
  227	 *      credential env var (GITHUB_PAT / CI_JOB_JWT / HTTP(S)_PROXY / ALL_PROXY /
  228	 *      DATABASE_URL / …) never leaks — not because a denylist happened to name it,
  229	 *      but because it is not a base var and nothing else is ever forwarded.
  230	 *   2. The policy `envDenylist` can then further RESTRICT the base set — an operator
  231	 *      may DROP a base var they do not want forwarded (e.g. deny PATH). It can only
  232	 *      remove, never add.
  233	 *
  234	 * The policy's `envAllowlist` is intentionally NOT applied to the review spawn: a
  235	 * read-only code reviewer needs no operator-specific/credential env, so an explicit
  236	 * allowlist can no longer inject ANY var into the review subprocess. This closes the
  237	 * credential-leak class BY CONSTRUCTION — there is no denylist left to be incomplete,
  238	 * because no non-base var is ever forwarded regardless of what an operator lists.
  239	 *
  240	 * NOTE ON THE POLICY: `envAllowlist` is unused HERE by design, but the rest of the
  241	 * policy (authorization + the finite-timeout ceiling) is still loaded, authorized,
  242	 * and enforced by authorizeReviewPolicy — only env-allowlist injection into the
  243	 * review spawn is dropped.
  244	 *
  245	 * The result is a concrete env object (never `process.env` by reference).
  246	 */
  247	export function buildRedactedEnv(base: NodeJS.ProcessEnv, policy: DispatchPolicy): NodeJS.ProcessEnv {
  248	  const denylist = new Set((policy.envDenylist ?? []).map(name => name.trim()).filter(Boolean));
  249	  const redacted: NodeJS.ProcessEnv = {};
  250	  for (const [name, value] of Object.entries(base)) {
  251	    if (value === undefined) continue;
  252	    // (1) Closed allowlist by construction: forward ONLY the hardcoded safe base set.
  253	    // The policy envAllowlist is intentionally NOT consulted — no operator entry can
  254	    // inject a credential/arbitrary var into the review spawn.
  255	    if (!isSafeBaseEnvName(name)) continue;
  256	    // (2) An explicit denylist can restrict (drop) a base var.
  257	    if (denylist.has(name)) continue;
  258	    redacted[name] = value;
  259	  }
  260	  return redacted;
  261	}
