  458	/**
  459	 * Parse + STRICTLY validate the host-A (Claude) findings from a JSON file. Must be a
  460	 * JSON array of `Finding` with EXACTLY the frozen fields — no missing, no extra, no
  461	 * wrong-typed keys. Any deviation fails closed with a descriptive error (host A is
  462	 * caller-authored, untrusted input; we neither silently drop its findings nor trust
  463	 * `JSON.parse` output that merely happens to carry the required fields).
  464	 *
  465	 * Sweep hardening: replaces the earlier hand-rolled per-field checks (which accepted
  466	 * and silently dropped EXTRA keys) with a strict Zod array — closing the same
  467	 * unknown-key trust-boundary gap fixed for the codex verdict schema.
  468	 */
  469	function loadHostAFindings(path: string): Finding[] {
  470	  let raw: string;
  471	  try {
  472	    raw = readFileSync(path, 'utf8');
  473	  } catch (err) {
  474	    throw new Error(`cross_host_review: cannot read hostAFindingsFile "${path}": ${err instanceof Error ? err.message : String(err)}`);
  475	  }
  476	  let parsed: unknown;
  477	  try {
  478	    parsed = JSON.parse(raw);
  479	  } catch (err) {
  480	    throw new Error(`cross_host_review: hostAFindingsFile "${path}" is not valid JSON: ${err instanceof Error ? err.message : String(err)}`);
  481	  }
  482	  if (!Array.isArray(parsed)) {
  483	    throw new Error(`cross_host_review: hostAFindingsFile "${path}" must contain a JSON array of Finding objects`);
  484	  }
  485	  const result = hostAFindingsSchema.safeParse(parsed);
  486	  if (!result.success) {
  487	    const issue = result.error.issues[0];
  488	    const where = issue && issue.path.length > 0 ? ` at ${issue.path.join('.')}` : '';
  489	    throw new Error(
  490	      `cross_host_review: hostAFindingsFile "${path}" is not a strict array of Finding objects`
  491	      + `${where}: ${issue ? issue.message : 'invalid'} `
  492	      + `(each entry must have EXACTLY severity/title/file/line/issue/fix — no missing, extra, or wrong-typed keys)`,
  493	    );
  494	  }
  495	  return result.data;
  496	}
