  548	/**
  549	 * F-004: load + ENFORCE the review-only dispatch policy that authorizes the codex
  550	 * review subprocess. Accepts a named policy (loaded from disk by checkDispatchPolicy)
  551	 * or an inline DispatchPolicy. FAIL-CLOSED — throws (so no codex leaf is ever
  552	 * spawned) when:
  553	 *   - no policy is supplied;
  554	 *   - the policy does not exist / is malformed / is otherwise refused;
  555	 *   - the policy does not grant allowReviewOnlyRealHostSubprocess for a codex host
  556	 *     (i.e. it does not actually authorize an independent read-only codex reviewer).
  557	 * Returns the normalized authorized policy so its env/timeout constraints can be
  558	 * applied to the spawn.
  559	 */
  560	function authorizeReviewPolicy(root: string, policy: string | DispatchPolicy | undefined): DispatchPolicy {
  561	  if (policy === undefined || (typeof policy === 'string' && policy.trim() === '')) {
  562	    throw new Error(
  563	      'cross_host_review: a review-only dispatch policy is required to spawn the codex review subprocess; '
  564	      + 'refusing to run an unconstrained subprocess (fail-closed). Pass --policy=<name> or an inline policy '
  565	      + 'that grants allowReviewOnlyRealHostSubprocess for a codex host.',
  566	    );
  567	  }
  568	  const check = checkDispatchPolicy(root, policy);
  569	  if (!check.authorized) {
  570	    throw new Error(
  571	      `cross_host_review: dispatch policy "${check.policy}" is not authorized (${check.status}); `
  572	      + `refusing to spawn the codex review subprocess. reasons: ${check.reasons.join('; ') || '(none)'}`,
