   287	/**
   288	 * Extract the trailing schema-valid verdict from `stdout`. Codex emits a
   289	 * transcript; the verdict MUST be its final structured message. This is
   290	 * deliberately fail-closed and NON-fragile:
   291	 *
   292	 *   1. The schema-valid verdict must be the LAST balanced top-level `{...}`
   293	 *      object in stdout. If the last balanced object is NOT schema-valid (e.g.
   294	 *      a different/trailing JSON object was emitted after the verdict), we do
   295	 *      NOT scan backwards past it — we return undefined (fail closed). "The
   296	 *      verdict is the final structured message" would otherwise be violated: a
   297	 *      clean pass followed by more content must never be trusted as pass.
   298	 *   2. Bug14 (HIGH — duplicate same-decision verdicts): there must be EXACTLY
   299	 *      ONE schema-valid verdict object in the entire stdout. A correct run emits
   300	 *      exactly one verdict, so ANY second schema-valid verdict — REGARDLESS of
   301	 *      whether its `decision` matches — makes the output ambiguous → return
   302	 *      undefined (fail closed). The earlier rule only failed closed on CONFLICTING
   303	 *      decisions, so an earlier `pass` carrying findings plus a later clean `pass`
   304	 *      was accepted (the earlier one silently discarded). We never silently pick
   305	 *      one, and we never trust a transcript that contains more than one verdict.
   306	 *   3. Real codex exec output may append a small amount of trailing HARNESS
   307	 *      metadata after the model's final message (whitespace, bare token-count
   308	 *      noise like `tokens used` / a lone number). That STRICT allowlist is
   309	 *      tolerated. ANY other trailing content — a trailing JSON OBJECT, a stray
   310	 *      word, a terse lowercase trailer (`actually fail` / `disregard`), or a
   311	 *      sentence — makes the verdict no longer the final content and MUST fail
   312	 *      closed. (Flipped from "reject if it looks like a sentence" to "reject
   313	 *      unless it is known-harmless harness noise" — the root fix for terse
   314	 *      trailers the old heuristic let through.)
   315	 *
   316	 * Returns undefined when there is no admissible trailing verdict.
   317	 */
   318	export function extractCodexReviewVerdict(stdout: string): CodexReviewVerdict | undefined {
   319	  // (3a) Strip trailing whitespace before locating the final structured object.
   320	  const trimmed = stdout.replace(/\s+$/u, '');
   321	  const objects = scanBalancedObjects(trimmed);
   322	  if (objects.length === 0) return undefined;
   323	
   324	  const last = objects[objects.length - 1];
   325	
   326	  // (3b) Anything AFTER the last balanced object must be KNOWN-HARMLESS harness
   327	  // noise (strict allowlist: whitespace + bare token count / `tokens used`). By
   328	  // construction no OTHER balanced object can follow the last one, so the tail is
   329	  // free-text; reject any tail that is not on the harness allowlist — including
   330	  // terse trailers like `actually fail` / `disregard verdict` — fail closed.
   331	  const tail = trimmed.slice(last.end);
   332	  if (!isTolerableTrailingHarness(tail)) return undefined;
   333	
   334	  // (1) The LAST balanced object must itself be the schema-valid verdict. If it is
   335	  // not, fail closed — do NOT reach backwards past a trailing invalid object.
   336	  const lastVerdict = parseVerdict(last.text);
   337	  if (!lastVerdict) return undefined;
   338	
   339	  // (2) Bug14 ambiguity guard: a correct run emits EXACTLY ONE verdict. If ANY OTHER
   340	  // balanced object is ALSO a schema-valid verdict — regardless of whether its
   341	  // decision matches — the transcript carries more than one verdict and is
   342	  // ambiguous → fail closed. (Tightened from "fail only on a DIFFERENT decision":
   343	  // an earlier `pass` with findings plus a later clean `pass` must not silently
   344	  // discard the earlier one and be trusted.)
   345	  for (let i = 0; i < objects.length - 1; i += 1) {
   346	    if (parseVerdict(objects[i].text)) return undefined;
   347	  }
   348	
   349	  return lastVerdict;
   350	}
