   352	/** Zod-validate one candidate substring as a verdict; undefined if it does not match. */
   353	function parseVerdict(candidate: string): CodexReviewVerdict | undefined {
   354	  let parsed: unknown;
   355	  try {
   356	    parsed = JSON.parse(candidate);
   357	  } catch {
   358	    return undefined;
   359	  }
   360	  const result = verdictSchema.safeParse(parsed);
   361	  return result.success ? { ...result.data } : undefined;
