   364	/**
   365	 * STRICT trailing-content contract (root fix — replaces the lax `looksLikeSentence`
   366	 * heuristic). After the last balanced verdict object, trailing content is admissible
   367	 * ONLY when every non-empty line is KNOWN-HARMLESS harness noise matching a strict
   368	 * allowlist:
   369	 *   - a bare number / comma-grouped number (a lone token count, e.g. `1,234`);
   370	 *   - the literal token-count line `tokens used` (optionally `tokens used: 1234`).
   371	 * ANY other trailing content — a stray word, a terse lowercase trailer like
   372	 * `actually fail` or `disregard`, a sentence, or another JSON object — makes this
   373	 * return false so extraction fails closed. The logic is flipped from "reject if it
   374	 * LOOKS LIKE a sentence" to "reject UNLESS it is on the known-harmless allowlist":
   375	 * a heuristic can be evaded by short terse trailers (`actually fail` is only two
   376	 * words, no terminal punctuation), but an allowlist cannot — anything unrecognized
   377	 * is rejected. This stays codex-version-agnostic by matching the shape of genuine
   378	 * harness bookkeeping, not a specific version string.
   379	 */
   380	const HARNESS_NOISE_LINE_PATTERNS: readonly RegExp[] = [
   381	  // A bare (optionally comma-grouped) number: a lone token count like `1234` / `1,234`.
   382	  /^\d{1,3}(,\d{3})*$/u,
   383	  /^\d+$/u,
   384	  // The token-count bookkeeping line, with or without a trailing count.
   385	  /^tokens used$/iu,
   386	  /^tokens used:\s*\d{1,3}(,\d{3})*$/iu,
   387	  /^tokens used:\s*\d+$/iu,
   388	];
   389	
   390	function isTolerableTrailingHarness(tail: string): boolean {
   391	  const lines = tail.split('\n').map(l => l.trim()).filter(l => l.length > 0);
   392	  for (const line of lines) {
   393	    if (!HARNESS_NOISE_LINE_PATTERNS.some(pattern => pattern.test(line))) return false;
   394	  }
   395	  return true;
   396	}
   397	
   398	interface BalancedObject { text: string; start: number; end: number; }
   399	
   400	/**
   401	 * Return every balanced `{...}` substring at the top brace-nesting level, with the
   402	 * character offsets `[start, end)` at which it occurs in `text` (end is exclusive).
   403	 */
   404	function scanBalancedObjects(text: string): BalancedObject[] {
   405	  const objects: BalancedObject[] = [];
   406	  let depth = 0;
   407	  let start = -1;
   408	  let inString = false;
   409	  let escaped = false;
   410	  for (let i = 0; i < text.length; i += 1) {
   411	    const ch = text[i];
   412	    if (inString) {
   413	      if (escaped) escaped = false;
   414	      else if (ch === '\\') escaped = true;
   415	      else if (ch === '"') inString = false;
   416	      continue;
   417	    }
   418	    if (ch === '"') {
   419	      inString = true;
   420	      continue;
   421	    }
   422	    if (ch === '{') {
   423	      if (depth === 0) start = i;
   424	      depth += 1;
   425	    } else if (ch === '}') {
   426	      if (depth > 0) {
   427	        depth -= 1;
   428	        if (depth === 0 && start >= 0) {
   429	          objects.push({ text: text.slice(start, i + 1), start, end: i + 1 });
   430	          start = -1;
   431	        }
   432	      }
   433	    }
   434	  }
   435	  return objects;
   436	}
